// compute the new hidden state in-place.
// PyTorch GRU gate order: [r, z, n] slices of size hidden_size each.
// pre_ih: (batch, 3*hidden) = W_ih @ x_t + b_ih
// pre_hh: (batch, 3*hidden) = W_hh @ h_{t-1} + b_hh
// h:      (batch, hidden)   = current hidden state (input and output)
__global__ void gru_cell_kernel(
    const float* __restrict__ pre_ih,  // (batch, 3*H)
    const float* __restrict__ pre_hh,  // (batch, 3*H)
    float* __restrict__ h,             // (batch, H) in-place update
    int batch_size,
    int hidden_size
) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch_size * hidden_size;
    if (tid >= total) return;

    int b = tid / hidden_size;
    int j = tid % hidden_size;
    int H = hidden_size;

    // Load gate preactivations
    float r_ih = pre_ih[b * 3*H + j];
    float z_ih = pre_ih[b * 3*H + H + j];
    float n_ih = pre_ih[b * 3*H + 2*H + j];

    float r_hh = pre_hh[b * 3*H + j];
    float z_hh = pre_hh[b * 3*H + H + j];
    float n_hh = pre_hh[b * 3*H + 2*H + j];

    // r = sigmoid(r_ih + r_hh)
    float r = 1.0f / (1.0f + __expf(-(r_ih + r_hh)));
    // z = sigmoid(z_ih + z_hh)
    float z = 1.0f / (1.0f + __expf(-(z_ih + z_hh)));
    // n = tanh(n_ih + r * n_hh)
    float n = tanhf(n_ih + r * n_hh);

    float h_prev = h[b * H + j];
    // h_new = (1 - z) * n + z * h_prev
    h[b * H + j] = (1.0f - z) * n + z * h_prev;
}

// Bias addition kernel: add bias vector to each row of a matrix
// mat: (batch, cols), bias: (cols)
__global__ void add_bias_kernel(
    float* __restrict__ mat,
    const float* __restrict__ bias,
    int batch_size,
    int cols
) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    if (tid >= batch_size * cols) return;
    int j = tid % cols;
    mat[tid] += bias[j];
}

static cublasHandle_t cublas_handle = nullptr;

static cublasHandle_t get_cublas_handle() {
    if (cublas_handle == nullptr) {
        cublasCreate(&cublas_handle);
    }
    return cublas_handle;
}

// Compute C = alpha * A * B^T + beta * C using cuBLAS
// A: (M, K), B: (N, K) => C: (M, N)
static void sgemm_NT(
    cublasHandle_t handle,
    int M, int N, int K,
    const float* A, const float* B, float* C,
    float alpha = 1.0f, float beta = 0.0f
) {
    // cuBLAS is column-major; we have row-major matrices.
    // C^T = B * A^T  in col-major terms
    // cublasGemmEx treats the first matrix as the "left" in col-major.
    // For row-major: C(M,N) = A(M,K) * B^T(K,N)
    // In col-major: C^T(N,M) = B(N,K) * A^T(K,M)
    // So: m=N, n=M, k=K, lda=K(B), ldb=K(A), ldc=N
    cublasSgemm(handle,
                CUBLAS_OP_T, CUBLAS_OP_N,
                N, M, K,
                &alpha,
                B, K,   // B^T: (K,N) stored as (N,K) row-major
                A, K,   // A: (M,K) row-major
                &beta,
                C, N);  // C: (M,N) row-major
}

torch::Tensor gruhidden_forward_cuda(
    torch::Tensor x,
    torch::Tensor h0,
    std::vector<torch::Tensor> w_ih,
    std::vector<torch::Tensor> w_hh,
    std::vector<torch::Tensor> b_ih,
    std::vector<torch::Tensor> b_hh,
    bool batch_first
) {
    // x: (seq_len, batch, input_size) if !batch_first
    //    (batch, seq_len, input_size) if batch_first
    // h0: (num_layers, batch, hidden_size)

    int seq_len, batch_size, input_size;
    if (batch_first) {
        batch_size = x.size(0);
        seq_len    = x.size(1);
        input_size = x.size(2);
    } else {
        seq_len    = x.size(0);
        batch_size = x.size(1);
        input_size = x.size(2);
    }

