// mat: (batch, cols), bias: (cols)
__global__ void add_bias_kernel(
    float* __restrict__ mat,
    const float* __restrict__ bias,
    int batch_size,
    int cols
) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    if (tid >= batch_size * cols) return;
    int j = tid % cols;
    mat[tid] += bias[j];
