// Compute C = alpha * A * B^T + beta * C using cuBLAS
// A: (M, K), B: (N, K) => C: (M, N)
static void sgemm_NT(
    cublasHandle_t handle,
    int M, int N, int K,
    const float* A, const float* B, float* C,
    float alpha = 1.0f, float beta = 0.0f
