    float n_ih = pre_ih[b * 3*H + 2*H + j] + b_ih[2*H + j];

    float r_hh = pre_hh[b * 3*H + j]       + b_hh[j];
    float z_hh = pre_hh[b * 3*H + H + j]   + b_hh[H + j];
    float n_hh = pre_hh[b * 3*H + 2*H + j] + b_hh[2*H + j];

    float r = 1.0f / (1.0f + expf(-(r_ih + r_hh)));
    float z = 1.0f / (1.0f + expf(-(z_ih + z_hh)));
    float n = tanhf(n_ih + r * n_hh);

    float h_prev = h[b * H + j];
    float h_new = (1.0f - z) * n + z * h_prev;
    h[b * H + j] = h_new;
    out_buf[b * H + j] = h_new;
}

static cublasHandle_t cublas_handle = nullptr;

static cublasHandle_t get_cublas_handle(cudaStream_t stream) {
    if (cublas_handle == nullptr) {
        cublasCreate(&cublas_handle);
    }
    cublasSetStream(cublas_handle, stream);
    return cublas_handle;
}

// Row-major: C(M,N) = A(M,K) * B^T(N,K)
static void sgemm_NT(
    cublasHandle_t handle,
    int M, int N, int K,
    const float* A, const float* B, float* C,
    float alpha = 1.0f, float beta = 0.0f
) {
    cublasSgemm(handle,
                CUBLAS_OP_T, CUBLAS_OP_N,
                N, M, K,
                &alpha,
                B, K,
                A, K,
                &beta,
                C, N);
}

torch::Tensor gruhidden_forward_cuda(
    torch::Tensor x,
    torch::Tensor h0,
    std::vector<torch::Tensor> w_ih,
    std::vector<torch::Tensor> w_hh,
    std::vector<torch::Tensor> b_ih,
    std::vector<torch::Tensor> b_hh,
    bool batch_first
) {
    int seq_len, batch_size, input_size;
    if (batch_first) {
        batch_size = x.size(0);
        seq_len    = x.size(1);
        input_size = x.size(2);
    } else {
        seq_len    = x.size(0);
        batch_size = x.size(1);
        input_size = x.size(2);
    }

    int num_layers  = (int)w_ih.size();
    int hidden_size = (int)w_hh[0].size(0) / 3;

    auto opts = torch::TensorOptions().dtype(torch::kFloat32).device(x.device());

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    cublasHandle_t handle = get_cublas_handle(stream);

    torch::Tensor x_seq;
    if (batch_first) {
        x_seq = x.transpose(0, 1).contiguous();
    } else {
        x_seq = x.contiguous();
    }

    auto h = h0.clone();
    auto pre_ih = torch::empty({batch_size, 3 * hidden_size}, opts);
    auto pre_hh = torch::empty({batch_size, 3 * hidden_size}, opts);

    std::vector<torch::Tensor> rolling(num_layers - 1);
    for (int l = 0; l < num_layers - 1; l++) {
        rolling[l] = torch::empty({batch_size, hidden_size}, opts);
    }

    for (int l = 0; l < num_layers; l++) {
        w_ih[l] = w_ih[l].contiguous();
        w_hh[l] = w_hh[l].contiguous();
        b_ih[l] = b_ih[l].contiguous();
        b_hh[l] = b_hh[l].contiguous();
    }

    const float* x_ptr = x_seq.data_ptr<float>();
    int threads = 256;

    for (int t = 0; t < seq_len; t++) {
        for (int l = 0; l < num_layers; l++) {
            int in_size = (l == 0) ? input_size : hidden_size;

            const float* w_ih_ptr = w_ih[l].data_ptr<float>();
            const float* w_hh_ptr = w_hh[l].data_ptr<float>();
            const float* b_ih_ptr = b_ih[l].data_ptr<float>();
            const float* b_hh_ptr = b_hh[l].data_ptr<float>();
            float* h_l = h.data_ptr<float>() + (long long)l * batch_size * hidden_size;

            const float* xt;
            if (l == 0) {
                xt = x_ptr + (long long)t * batch_size * input_size;
            } else {
                xt = rolling[l-1].data_ptr<float>();
            }

            sgemm_NT(handle, batch_size, 3*hidden_size, in_size,
                     xt, w_ih_ptr, pre_ih.data_ptr<float>());

            sgemm_NT(handle, batch_size, 3*hidden_size, hidden_size,
                     h_l, w_hh_ptr, pre_hh.data_ptr<float>());

            int n = batch_size * hidden_size;
            int blk = (n + threads - 1) / threads;
            if (l < num_layers - 1) {
                gru_cell_and_store_kernel<<<blk, threads, 0, stream>>>(
                    pre_ih.data_ptr<float>(),
                    pre_hh.data_ptr<float>(),
                    b_ih_ptr,
                    b_hh_ptr,
                    h_l,
                    rolling[l].data_ptr<float>(),
                    batch_size, hidden_size);
            } else {
                gru_cell_kernel<<<blk, threads, 0, stream>>>(
                    pre_ih.data_ptr<float>(),
                    pre_hh.data_ptr<float>(),
                    b_ih_ptr,
                    b_hh_ptr,
                    h_l,
                    batch_size, hidden_size);
            }
        }
    }

    return h;
}
